    int tool_call_end_id = -1;
    int think_id = -1;
    int think_end_id = -1;
    int attn_cnt = 32;
    int sconv_cnt = 0;
    int gdr_cnt = 0;
    int rope_head_dim = 64;

    enum RoPE_Type {
        RoPE = 0,
