12	ncnn::Mat llm_run_text_embed(ncnn::Net& embed_net, const std::vector<int>& input_ids) {
13	    ncnn::Mat input_ids_mat((int)input_ids.size(), 1, (void*)input_ids.data());
14	    input_ids_mat = input_ids_mat.clone();
15	
16	    ncnn::Mat token_embed;
17	    ncnn::Extractor ex = embed_net.create_extractor();
18	    ex.input("in0", input_ids_mat);
19	    ex.extract("out0", token_embed);
20	    return token_embed;
21	}
22	
23	ncnn::Mat llm_run_text_embed(ncnn::Net& embed_net, int token_id) {
24	    ncnn::Mat input_id_mat(1, 1, (void*)&token_id);
25	    input_id_mat = input_id_mat.clone();
26	
27	    ncnn::Mat token_embed;
28	    ncnn::Extractor ex = embed_net.create_extractor();
29	    ex.input("in0", input_id_mat);
30	    ex.extract("out0", token_embed);
31	    return token_embed;
32	}
33	
34	ncnn::Mat llm_run_decoder_with_kv(ncnn::Net& decoder_net,
35	                                  const ncnn::Mat& embeds,
36	                                  const ncnn::Mat& mask,
37	                                  const ncnn::Mat& cos_cache,
38	                                  const ncnn::Mat& sin_cache,
39	                                  KVCache& kv_cache,
40	                                  int attn_cnt,
41	                                  bool is_prefill) {
42	    ncnn::Mat decode_out;
43	    ncnn::Extractor ex = decoder_net.create_extractor();
44	    ex.input("in0", embeds);
45	    ex.input("in1", mask);
46	    ex.input("in2", cos_cache);
47	    ex.input("in3", sin_cache);
48	
49	    if (!is_prefill) {
50	        for (int i = 0; i < attn_cnt; i++) {
51	            char name_k_in[16], name_v_in[16];
52	            std::snprintf(name_k_in, sizeof(name_k_in), "cache_k%d", i);
53	            std::snprintf(name_v_in, sizeof(name_v_in), "cache_v%d", i);
54	            ex.input(name_k_in, kv_cache[i].first);
55	            ex.input(name_v_in, kv_cache[i].second);
56	        }
57	    }
58	
59	    for (int i = 0; i < attn_cnt; i++) {
60	        char name_k_out[32], name_v_out[32];
61	        std::snprintf(name_k_out, sizeof(name_k_out), "out_cache_k%d", i);
62	        std::snprintf(name_v_out, sizeof(name_v_out), "out_cache_v%d", i);
63	        ncnn::Mat k_cache, v_cache;
64	        ex.extract(name_k_out, k_cache);
65	        ex.extract(name_v_out, v_cache);
66	        if (is_prefill) {
67	            kv_cache.emplace_back(std::move(k_cache), std::move(v_cache));
68	        } else {
69	            kv_cache[i] = std::make_pair(std::move(k_cache), std::move(v_cache));
70	        }
71	    }
72	
73	    ex.extract("out0", decode_out);
74	    return decode_out;
75	}
76	
77	ncnn::Mat llm_run_lm_head(ncnn::Net& lm_head_net, const ncnn::Mat& hidden_states) {
